// HasUsageLog applies the HasEdge predicate on the "usage_log" edge.
func HasUsageLog() predicate.UsageUpstreamCostEvidence {
	return predicate.UsageUpstreamCostEvidence(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, UsageLogTable, UsageLogColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasUsageLogWith applies the HasEdge predicate on the "usage_log" edge with a given conditions (other predicates).
func HasUsageLogWith(preds ...predicate.UsageLog) predicate.UsageUpstreamCostEvidence {
	return predicate.UsageUpstreamCostEvidence(func(s *sql.Selector) {
		step := newUsageLogStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.UsageUpstreamCostEvidence) predicate.UsageUpstreamCostEvidence {
	return predicate.UsageUpstreamCostEvidence(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.UsageUpstreamCostEvidence) predicate.UsageUpstreamCostEvidence {
	return predicate.UsageUpstreamCostEvidence(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.UsageUpstreamCostEvidence) predicate.UsageUpstreamCostEvidence {
	return predicate.UsageUpstreamCostEvidence(sql.NotPredicates(p))
}
